import { expect, it } from "vitest";
import {
  asResourceKey,
  asRobloxAssetId,
  refreshLiveState,
  type BedrockState,
} from '@bedrock-rbx/core'

it('Example 1', () => {
  const state: BedrockState = {
    environment: 'production',
    version: 1,
    resources: [
      {
        key: asResourceKey('gems'),
        kind: 'developerProduct',
        name: 'Gems',
        description: '100 gems',
        price: 100,
        outputs: { productId: asRobloxAssetId('123') },
      },
    ],
  }
  const refreshed = refreshLiveState(state, {
    developerProduct: new Map([
      [
        asRobloxAssetId('123'),
        {
          kind: 'developerProduct',
          outputs: {},
          price: 120,
        },
      ],
    ]),
  })
  expect(refreshed).toEqual({
    ...state,
    resources: [{ ...state.resources[0], price: 120 }],
  })
  expect(refreshed).not.toBe(state)
  expect(state.resources[0]).toMatchObject({ price: 100 })
})
